@Composable
fun NavigationGraph(startDestination: String = "auth_flow") {
    val authViewModel: AuthViewModel = hiltViewModel()
    val cartViewModel: CartViewModel = hiltViewModel()
    val profileViewModel: ProfileViewModel = hiltViewModel()
    val homeViewModel: HomeViewModel = hiltViewModel()
    val navController = rememberNavController()

    LaunchedEffect(authState) { ... } // Handle auth state changes

    NavHost(navController, startDestination) {
        authGraph(navController, authViewModel)
        composable(Screen.Main.route) { MainScreen(...) }
        composable(Screen.Home.route) { HomeScreen(...) }
        composable(Screen.Search.route) { SearchScreen(...) }
        composable(Screen.Cart.route) { CartScreen(...) }
        addressGraph(navController)
        restaurantGraph(navController, cartViewModel)
        rideshareGraph(navController)
        profileGraph(navController, authViewModel, profileViewModel)
    }
}

@AndroidEntryPoint
class CustomerFirebaseMessagingService : DollorFirebaseMessagingService() {
    @Inject lateinit var dollorRepository: DollorRepository

    override fun onNotificationReceived(type: String, data: Map<String, String>) {
        when (type) {
            TYPE_ORDER_CONFIRMED, TYPE_ORDER_PREPARING, TYPE_ORDER_READY,
            TYPE_ORDER_PICKED_UP, TYPE_ORDER_DELIVERED, TYPE_ORDER_CANCELLED -> handleOrderUpdate(data)
            TYPE_RIDE_ACCEPTED, TYPE_DRIVER_ARRIVING, TYPE_RIDE_STARTED,
            TYPE_RIDE_COMPLETED, TYPE_RIDE_CANCELLED -> handleRideUpdate(data)
            TYPE_PROMOTION -> handlePromotion(data)
        }
    }

    override fun sendTokenToServer(token: String) {
        dollorRepository.registerPushToken(token, "android", "fcm")
    }
}

SecureStorage uses ReentrantReadWriteLock for thread-safe read/write operations:
private val lock = java.util.concurrent.locks.ReentrantReadWriteLock()
private val readLock = lock.readLock()
private val writeLock = lock.writeLock()

Read operations use readLock.lock()/unlock(), write operations use writeLock.lock()/unlock()

